package cn.mop.persistence;

import cn.mop.domain.DomainException;
import cn.mop.domain.inspection.InspectionTemplate;
import cn.mop.domain.inspection.InspectionTemplate.Item;
import cn.mop.domain.inspection.InspectionTemplateRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import javax.sql.DataSource;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Actual existing PG identities; own synthetic templates are archived, never deleted. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresInspectionTemplateIntegrationTest {
    static final String A="55000000-0000-4000-8000-000000000001",B="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresInspectionTemplateRepository repository;static String admin;
    final List<Entry> owned=new ArrayList<>();
    @BeforeAll static void connect()throws Exception {
        String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(6);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);
        mapper=new ObjectMapper().registerModule(new JavaTimeModule()).setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);repository=new PostgresInspectionTemplateRepository(pool,platform);admin=actor("padmin");assertEquals("padmin",platform.membership(admin,B).orElseThrow().role());assertEquals(List.of(),repository.readinessProblems());
    }
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),A).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor,String tenant){return new Access(actor,tenant,platform.membership(actor,tenant).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Access admin(){return access(admin,B);}
    static InspectionTemplate definition(String name){return new InspectionTemplate("custom_device",name,List.of(new Item("firmware","安全合规","固件版本",null),new Item("backup","配置备份","人工验证","合成说明\n不是扫描")));}
    static Object command(Access a,String id,String route,String key,String hash,Supplier<Object> work){return platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->repository.authorizeWrite(a,id),work);}
    Entry create(String name){Access a=admin();var value=definition(name);Entry entry=(Entry)command(a,null,"POST /integration/inspection-templates",UUID.randomUUID().toString(),value.fingerprint(),()->repository.create(a,0,value));owned.add(entry);return entry;}
    Entry update(Entry before,InspectionTemplate value){Access a=access(admin,before.tenantId());return (Entry)command(a,before.id(),"PATCH /integration/inspection-templates/"+before.id(),UUID.randomUUID().toString(),value.fingerprint(),()->repository.update(a,before.id(),before.version(),value));}
    Entry archive(Access a,Entry before){return (Entry)command(a,before.id(),"POST /integration/inspection-templates/"+before.id()+"/archive",UUID.randomUUID().toString(),"a".repeat(64),()->repository.archive(a,before.id(),before.version()));}
    Entry restore(Entry before,InspectionTemplate value){Access a=access(admin,before.tenantId());return (Entry)command(a,before.id(),"POST /integration/inspection-templates/"+before.id()+"/restore",UUID.randomUUID().toString(),value.fingerprint(),()->repository.restore(a,before.id(),before.version(),value));}
    @AfterEach void archiveOnlyOwnedRecords(){for(Entry entry:owned){Access a=access(admin,entry.tenantId());Entry current=repository.get(a,entry.id());assertEquals(admin,current.createdBy());assertTrue(current.snapshot().definition().name().startsWith("SYNTHETIC_"));if(!current.archived())archive(a,current);}}
    static List<Long> counts()throws Exception{var result=new ArrayList<Long>();try(var c=pool.getConnection();var s=c.createStatement()){for(String table:List.of("mop_inspection_template","mop_inspection_template_revision","mop_inspection_template_item","mop_audit","mop_idempotency")){try(var r=s.executeQuery("SELECT count(*) FROM public."+table)){r.next();result.add(r.getLong(1));}}}return result;}
    static JsonNode json(Object value)throws Exception{return mapper.readTree(mapper.writeValueAsBytes(value));}
    @Test void createPersistsDefinitionFingerprintAuditAndOriginalReceiptAtomically()throws Exception{var before=counts();var entry=create("SYNTHETIC_CREATE_"+UUID.randomUUID());assertEquals(1,entry.version());assertEquals(entry,repository.get(admin(),entry.id()));assertEquals("UNVERIFIED",entry.snapshot().definition().approvalStatus());assertFalse(entry.snapshot().definition().publishable());assertEquals(List.of(before.get(0)+1,before.get(1)+1,before.get(2)+2,before.get(3)+1,before.get(4)+1),counts());}
    @Test void freshRepositoryReadsImmutableCommittedDefinition(){var entry=create("SYNTHETIC_FRESH");var fresh=new PostgresInspectionTemplateRepository(pool,new PostgresPlatformRepository(pool,mapper));assertEquals(entry,fresh.get(admin(),entry.id()));assertThrows(UnsupportedOperationException.class,()->entry.snapshot().definition().items().clear());}
    @Test void nextDefinitionKeepsOldVersionAndExplicitNullOrEmpty(){var one=create("SYNTHETIC_REVISION");var newDefinition=new InspectionTemplate("fifth_type","SYNTHETIC_NEXT",List.of(new Item("new_item","新分组","😀","")));var two=update(one,newDefinition);assertEquals(2,two.version());assertEquals(one.createdAt(),two.createdAt());var history=repository.history(admin(),one.id(),10,null);assertEquals(List.of(2L,1L),history.stream().map(Revision::version).toList());assertEquals(one.snapshot(),history.get(1).snapshot());assertEquals(newDefinition,history.get(0).snapshot().definition());assertEquals("",history.get(0).snapshot().definition().items().get(0).instruction());assertEquals(List.of(1L),repository.history(admin(),one.id(),10,2L).stream().map(Revision::version).toList());}
    @Test void staleVersionDoesNotOverwriteAnyHistory(){var one=create("SYNTHETIC_CAS");var two=update(one,definition("SYNTHETIC_CAS_NEXT"));assertEquals(409,assertThrows(DomainException.class,()->update(one,definition("SYNTHETIC_STALE"))).status);assertEquals(two,repository.get(admin(),one.id()));}
    @Test void archiveCopiesExactDefinitionAndRestoreRequiresExplicitCurrentVersion(){var one=create("SYNTHETIC_ARCHIVE");var archived=archive(admin(),one);assertTrue(archived.archived());assertEquals(one.snapshot().definition(),archived.snapshot().definition());assertEquals(one.snapshot().contentSha256(),archived.snapshot().contentSha256());assertEquals(409,assertThrows(DomainException.class,()->update(archived,definition("SYNTHETIC_BAD"))).status);var restored=restore(archived,definition("SYNTHETIC_RESTORED"));assertFalse(restored.archived());assertEquals(3,restored.version());assertEquals(409,assertThrows(DomainException.class,()->restore(restored,definition("SYNTHETIC_BAD"))).status);}
    @Test void otherCurrentRolesCannotMaintainUnpublishedTemplates()throws Exception{var before=counts();for(String role:List.of("msp","viewer","tadmin")){Access a=access(actor(role),A);assertEquals(403,assertThrows(DomainException.class,()->repository.list(a,"",null,View.ALL,10,null,null)).status);assertEquals(403,assertThrows(DomainException.class,()->command(a,null,"POST /integration/inspection-denied",UUID.randomUUID().toString(),"b".repeat(64),()->repository.create(a,0,definition("SYNTHETIC_DENIED")))).status);}assertEquals(before,counts());}
    @Test void foreignTenantResourcesAre404ForAnOtherwiseAuthorizedAdministrator(){var entry=create("SYNTHETIC_FOREIGN");Access a=access(admin,A);assertEquals(404,assertThrows(DomainException.class,()->repository.get(a,entry.id())).status);assertEquals(404,assertThrows(DomainException.class,()->archive(a,entry)).status);assertEquals(404,assertThrows(DomainException.class,()->repository.history(a,entry.id(),10,null)).status);assertEquals(1,repository.get(admin(),entry.id()).version());}
    @Test void originalReceiptReplaysAfterArchiveAndRejectsChangedBodyOrStaleMembership()throws Exception{Access a=admin();String key=UUID.randomUUID().toString(),route="POST /integration/inspection-replay";var value=definition("SYNTHETIC_REPLAY");Object original=command(a,null,route,key,value.fingerprint(),()->repository.create(a,0,value));Entry entry=(Entry)original;owned.add(entry);archive(a,entry);var before=counts();Object replay=command(a,null,route,key,value.fingerprint(),()->{throw new AssertionError("duplicate command");});assertEquals(json(original),json(replay));assertEquals(before,counts());assertTrue(repository.get(a,entry.id()).archived());assertEquals(409,assertThrows(DomainException.class,()->command(a,null,route,key,"f".repeat(64),()->null)).status);Access stale=new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId());assertEquals(401,assertThrows(DomainException.class,()->command(stale,null,route,key,value.fingerprint(),()->null)).status);}
    @Test void revokedCallbackRunsBeforeOriginalReceiptWithoutMutatingUsers()throws Exception{Access a=admin();String key=UUID.randomUUID().toString(),route="POST /integration/inspection-callback";var value=definition("SYNTHETIC_CALLBACK");owned.add((Entry)command(a,null,route,key,value.fingerprint(),()->repository.create(a,0,value)));assertEquals(403,assertThrows(DomainException.class,()->platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,value.fingerprint(),a.permissionVersion(),()->{throw new DomainException(403,"ACTION_FORBIDDEN","Isolated authorization callback denial");},()->null)).status);}
    @Test void callerFailureRollsBackHeadItemsHistoryAuditAndReceipt()throws Exception{var before=counts();Access a=admin();var value=definition("SYNTHETIC_ROLLBACK");assertThrows(IllegalStateException.class,()->command(a,null,"POST /integration/inspection-rollback",UUID.randomUUID().toString(),value.fingerprint(),()->{repository.create(a,0,value);throw new IllegalStateException("Synthetic rollback");}));assertEquals(before,counts());}
    @Test void unprotectedWritesAndNestedIndependentReadsFailWithoutMutation()throws Exception{Access a=admin();var before=counts();assertThrows(IllegalStateException.class,()->repository.create(a,0,definition("SYNTHETIC_UNPROTECTED")));assertThrows(IllegalStateException.class,()->repository.authorizeWrite(a,null));assertThrows(IllegalStateException.class,()->command(a,null,"POST /integration/inspection-nested",UUID.randomUUID().toString(),"a".repeat(64),()->repository.list(a,"",null,View.ALL,10,null,null)));assertEquals(before,counts());}
    @Test void boundedLiteralAndDeviceFiltersKeepStablePagesAndArchiveViews(){String marker="SYNTHETIC_PAGE_"+UUID.randomUUID();for(int i=0;i<12;i++)create(marker+"_"+i);var first=repository.list(admin(),marker,"custom_device",View.CURRENT,10,null,null);assertEquals(10,first.size());var last=first.get(9);var second=repository.list(admin(),marker,"custom_device",View.CURRENT,10,last.createdAt(),last.id());assertEquals(2,second.size());var ids=new HashSet<String>();first.forEach(e->assertTrue(ids.add(e.id())));second.forEach(e->assertTrue(ids.add(e.id())));assertTrue(repository.list(admin(),marker,"other_type",View.CURRENT,10,null,null).isEmpty());var literal=create("SYNTHETIC_Ä_%_"+UUID.randomUUID());assertEquals(literal.id(),repository.list(admin(),literal.snapshot().definition().name().toLowerCase(Locale.ROOT),null,View.CURRENT,10,null,null).get(0).id());archive(admin(),literal);assertTrue(repository.list(admin(),literal.snapshot().definition().name(),null,View.CURRENT,10,null,null).isEmpty());assertEquals(literal.id(),repository.list(admin(),literal.snapshot().definition().name(),null,View.ARCHIVED,10,null,null).get(0).id());}
    @Test void successfulReadonlyCallsAddNoAuditOrOtherRows()throws Exception{var entry=create("SYNTHETIC_READONLY");var before=counts();repository.get(admin(),entry.id());repository.list(admin(),"SYNTHETIC_READONLY",null,View.ALL,10,null,null);repository.history(admin(),entry.id(),10,null);assertEquals(before,counts());}
    @Test void invalidScopeTracePaginationAndNullDefinitionAreRejected()throws Exception{Access a=admin();var before=counts();for(int n:new int[]{0,102})assertEquals(400,assertThrows(DomainException.class,()->repository.list(a,"",null,View.ALL,n,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->repository.list(a,"",null,View.ALL,10,Instant.EPOCH,null)).status);assertEquals(400,assertThrows(DomainException.class,()->repository.list(a,"",null,View.ALL,10,Instant.EPOCH.plusNanos(1),UUID.randomUUID().toString())).status);assertEquals(400,assertThrows(DomainException.class,()->repository.list(new Access(a.actorId(),a.tenantId(),a.permissionVersion(),"bad trace"),"",null,View.ALL,10,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->command(a,null,"POST /integration/inspection-null",UUID.randomUUID().toString(),"a".repeat(64),()->repository.create(a,0,null))).status);assertEquals(before,counts());}
    @Test void staleOrMissingMembershipCannotReadEvenAnExistingTemplate(){var entry=create("SYNTHETIC_STALE_ACCESS");var a=admin();assertEquals(401,assertThrows(DomainException.class,()->repository.get(new Access(a.actorId(),a.tenantId(),a.permissionVersion()+1,a.traceId()),entry.id())).status);assertEquals(401,assertThrows(DomainException.class,()->repository.get(new Access(UUID.randomUUID().toString(),B,1,a.traceId()),entry.id())).status);}
    @Test void sameKeyConcurrentCreateProducesOneCommitAndExactOriginalReceipt()throws Exception{Access a=admin();var definition=definition("SYNTHETIC_CONCURRENT_KEY");String key=UUID.randomUUID().toString(),route="POST /integration/inspection-key";var before=counts();var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var go=new CountDownLatch(1);try{Callable<JsonNode> action=()->{ready.countDown();assertTrue(go.await(5,TimeUnit.SECONDS));return json(command(a,null,route,key,definition.fingerprint(),()->repository.create(a,0,definition)));};var x=executor.submit(action);var y=executor.submit(action);assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();var result=x.get(10,TimeUnit.SECONDS);assertEquals(result,y.get(10,TimeUnit.SECONDS));owned.add(repository.get(a,result.path("id").asText()));}finally{executor.shutdownNow();}assertEquals(List.of(before.get(0)+1,before.get(1)+1,before.get(2)+2,before.get(3)+1,before.get(4)+1),counts());}
    @Test void twoRealConnectionsWithSameVersionHaveExactlyOneWinner()throws Exception{var entry=create("SYNTHETIC_CONCURRENT_VERSION");var executor=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(2);var go=new CountDownLatch(1);try{Callable<Integer> action=()->{ready.countDown();assertTrue(go.await(5,TimeUnit.SECONDS));try{update(entry,definition("SYNTHETIC_WINNER_"+UUID.randomUUID()));return 200;}catch(DomainException e){return e.status;}};var x=executor.submit(action);var y=executor.submit(action);assertTrue(ready.await(5,TimeUnit.SECONDS));go.countDown();assertEquals(Set.of(200,409),Set.of(x.get(10,TimeUnit.SECONDS),y.get(10,TimeUnit.SECONDS)));}finally{executor.shutdownNow();}assertEquals(2,repository.get(admin(),entry.id()).version());assertEquals(2,repository.history(admin(),entry.id(),10,null).size());}
    @Test void actualAuditStatementFailureRollsBackEverything()throws Exception{fault(true);}
    @Test void tamperedPersistedItemCannotReturnAValidSnapshotOrReceipt()throws Exception{fault(false);}
    void fault(boolean audit)throws Exception{
        DataSource injected=(DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{DataSource.class},(proxy,method,args)->{
            if(method.getName().equals("getConnection")){Connection real=pool.getConnection();return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{Connection.class},(cp,cm,ca)->{
                if(cm.getName().equals("prepareStatement")&&ca[0] instanceof String sql){
                    if(audit&&sql.startsWith("INSERT INTO public.mop_audit"))throw new SQLException("Synthetic audit rejection","22012");
                    if(!audit&&sql.startsWith("INSERT INTO public.mop_inspection_template_item")){PreparedStatement statement=(PreparedStatement)cm.invoke(real,ca);return java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{PreparedStatement.class},(sp,sm,sa)->{if(sm.getName().equals("setString")&&Integer.valueOf(7).equals(sa[0]))sa=new Object[]{7,"Synthetic changed label"};try{return sm.invoke(statement,sa);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}});}
                }
                try{return cm.invoke(real,ca);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
            });}
            try{return method.invoke(pool,args);}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}
        });
        var otherPlatform=new PostgresPlatformRepository(injected,mapper);var other=new PostgresInspectionTemplateRepository(injected,otherPlatform);Access a=admin();var before=counts();
        assertEquals(503,assertThrows(DomainException.class,()->otherPlatform.idempotentAuthorized(a.actorId(),a.tenantId(),"POST /integration/inspection-fault",UUID.randomUUID().toString(),"a".repeat(64),a.permissionVersion(),()->other.authorizeWrite(a,null),()->other.create(a,0,definition("SYNTHETIC_FAULT")))).status);assertEquals(before,counts());
    }
}
